    explicit BatchFunGuard(std::function<void(const NodePtr &)> fn)
        : ScopedValue(g_batch_fun, std::move(fn)) {}
};

struct BatchExeGuard : ScopedValue<bool> {
    explicit BatchExeGuard(bool flag)
        : ScopedValue(g_batch_execute, flag) {}
};

