    void closeNode(const NodePtr &node) {
        if (!node) return;

        ConditionalUniqueLock<ConditionalSharedMutex> lock(m_graphMutex);
        NodeSet closedNodes;
        cascadeCloseDependents(node, closedNodes);
    }

