                             std::is_same_v<Op, DivOp> &&
                                 std::is_integral_v<typename L::value_type> &&
                                 std::is_integral_v<typename R::value_type>,
                             double,
                             std::remove_cvref_t<std::common_type_t<typename L::value_type, typename R::value_type>>>> {
private:
