        if (TR::checkTrig()) {
            bool change = true;
            if constexpr (!VoidType<Type>) {
                change = this->updateValue(evaluate());
            } else {
                evaluate();
            }
            if constexpr (Notify) {
                this->notify(change);
            }
        }
    }

