        requires Convertable<Type, T>
    constexpr ValueWrapper(Type &&t) noexcept(std::is_nothrow_constructible_v<T, Type>)
        : m_value(std::forward<Type>(t)) {}

    [[nodiscard]] constexpr const T &evaluate() const noexcept {
        return m_value;
