    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseAndAssignable<Type, U>)
    React &operator&=(const U &rhs) {
        atomicBitwiseAndAssign(*getPtr(), rhs);
        return *this;
    }

