    /// @brief Compound subtraction assignment operator (-=)
    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && SubtractAssignable<Type, U>)
    React &operator-=(const U &rhs) {
        atomicSubtractAssign(*getPtr(), rhs);
