 * @tparam Fun Callable type to execute within the batch.
 * @param fun A function containing batched operations to be executed.
 */
template <InvocableType Fun>
void batchExecute(Fun &&fun) {
    Batch batch{std::forward<Fun>(fun)};
    batch.execute();
}

