template <NonReact T>
auto create(T &&t) {
    if constexpr (IsBinaryOpExpr<std::remove_cvref_t<T>>) {
        return expr(std::forward<T>(t));
    } else if constexpr (InvocableType<T>) {
        return calc(std::forward<T>(t));
