    Expression(U &&expr) : m_expr(std::forward<U>(expr)) {
    }

protected:
    /// @brief Sets the unary operator expression as the current source.
    void setOpExpr() {
        this->setSource([this]() {
            return m_expr();
        });
    }

private:
    UnaryOpExpr<Op, T> m_expr;
};

