     * @brief Closes this reactive node and cleans up any related state.
     */
    void close() {
        ObserverGraph::getInstance().closeNode(this->shared_from_this());
        if constexpr (HasField<Type>) {
            FieldGraph::getInstance().deleteObj(this->getValue().getId());
