    React &operator=(const React &other) noexcept {
        if (this != &other) {
            safeReleaseRef();
            m_weakPtr = other.m_weakPtr;
            safeAddRef();
        }
        return *this;
    }

    /// @brief Move assignment.
    React &operator=(React &&other) noexcept {
        if (this != &other) {
            safeReleaseRef();
            m_weakPtr = std::move(other.m_weakPtr);
            other.m_weakPtr.reset();
