 * @param t The input value, expression, or callable.
 * @return Corresponding reactive wrapper.
 */
template <NonReact T>
auto create(T &&t) {
    if constexpr (IsBinaryOpExpr<std::remove_cvref_t<T>>) {
        return expr(std::forward<T>(t));
    } else if constexpr (InvocableType<T>) {
