    ~React() {
        safeReleaseRef();
    }

    /// @brief Copy constructor.
    React(const React &other) noexcept : m_weakPtr(other.m_weakPtr) {
        safeAddRef();
    }

    /// @brief Move constructor.
    React(React &&other) noexcept : m_weakPtr(std::move(other.m_weakPtr)) {
        other.m_weakPtr.reset();
