    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && BitwiseXorAssignable<Type, U>)
    React &operator^=(const U &rhs) {
        atomicBitwiseXorAssign(*getPtr(), rhs);
        return *this;
    }

