    [[nodiscard]] decltype(auto) operator()() const {
        REACTION_REGISTER_THREAD();
        if (g_reg_fun) {
            std::invoke(g_reg_fun, getPtr());
        }
        return get();
    }

    /// @brief Returns the current value.
    [[nodiscard]] decltype(auto) get() const {
        REACTION_REGISTER_THREAD();
        return getPtr()->get();
    }

