     * @brief Destroy the Batch object.
     *
     * Unregisters this batch from active tracking if not already closed,
     * allowing reset operations on previously protected nodes.
     */
    ~Batch() {
        if (!m_isClosed) {
            // Only unregister if we haven't already closed
            m_isClosed = true;
