     * 2. Triggers valueChanged() on all collected observer nodes
     */
    void execute() {
        BatchExeGuard g(true);
        std::invoke(m_fun);

        for (auto &node : m_batchNodes) {
            if (auto wp = node.lock()) [[likely]]
                wp->changedNoNotify();
