        -> decltype(std::declval<T>().try_lock_shared()) {
        if (ThreadManager::getInstance().isThreadSafetyEnabled()) [[likely]] {
            return m_mutex.try_lock_shared();
        }
        return true; // Always succeed when thread safety is disabled
    }

private:
    MutexType m_mutex;
};

