using ConditionalSharedMutex = ConditionalMutexWrapper<std::shared_mutex>;

/**
 * @brief Conditional mutex that provides no-op when thread safety is disabled.
 */
using ConditionalMutex = ConditionalMutexWrapper<std::mutex>;

