     * @param impl The ReactImpl instance                                              \
     * @param rhs The right-hand side value                                            \
     */                                                                                \
    template <typename Impl, typename U>                                               \
    constexpr void atomic##name##Assign(Impl &impl, const U &rhs) {                    \
