        m_threadSafetyEnabled.store(REACTION_THREAD_SAFETY_MODE, std::memory_order_release);
        m_firstThreadId.store(std::thread::id{}, std::memory_order_release);
        m_safetyVersion.fetch_add(1, std::memory_order_release);

