    // Conditional SBO for medium-sized types
    static constexpr bool conditional_sbo = sizeof(T) <= SBOConfig::CONDITIONAL_SBO_SIZE &&
                                           sizeof(T) > SBOConfig::ALWAYS_SBO_SIZE &&
                                           is_sbo_eligible;

