#define REACTION_REGISTER_THREAD()                                                        \
    do {                                                                                  \
        static thread_local reaction::ThreadRegistrationGuard thread_guard_##__COUNTER__; \
        (void)thread_guard_##__COUNTER__;                                                 \
    } while (0)

