        if constexpr (always_sbo) {
            return reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
        } else {
            // Runtime branch for conditional_sbo types
            if (is_sbo_storage) {
                return reinterpret_cast<Type*>(const_cast<char*>(storage.buffer));
            } else {
                return storage.heap_ptr.get();
            }
        }
    }

