     * @param t The initialization value for the resource.
     */
    template <typename T>
        requires(!std::is_same_v<std::remove_cvref_t<T>, ResourceImpl<Type>>)
    ResourceImpl(T &&t) : m_ptr(std::make_unique<Type>(std::forward<T>(t))) {
    }

