    template <typename F, HasArguments... A>
    void set(F &&f, A &&...args) {
        this->setSource(std::forward<F>(f), std::forward<A>(args)...);
        this->notify();
    }

    /**
     * @brief Overload of set with only function input. Dependency is auto-tracked.
     */
    template <typename F>
    void set(F &&f) {
        {
            RegFunGuard g([this](const NodePtr &node) {
                this->addObCb(node);
