    [[nodiscard]] auto getRaw() const {
        return this->getRawPtr();
    }

    /**
     * @brief Sets a new expression source and dependencies.
     *
     * @param f    Expression function/lambda.
     * @param args Additional arguments (usually reactive inputs).
