                allocated = true;
            }
        }

        explicit StackGuard(size_t size) noexcept : allocated(false) {
            if (canAllocate(size)) {
                current_usage.fetch_add(size, std::memory_order_relaxed);
                allocated = true;
            }
        }

        ~StackGuard() noexcept {
            if (allocated) {
                current_usage.fetch_sub(Size, std::memory_order_relaxed);
            }
        }

