namespace std {

using namespace reaction;
template <typename Expr, typename Type, IsInvalidation IV, IsTrigger TR>
struct hash<React<Expr, Type, IV, TR>> {
    std::size_t operator()(const React<Expr, Type, IV, TR> &react) const noexcept {
