    void safeAddRef() noexcept {
        if (auto p = m_weakPtr.lock()) [[likely]]
            p->addWeakRef();
    }

    /**
     * @brief Safely decrement the weak reference count.
     *
     * Only decrements if the weak pointer can be locked successfully.
     */
    void safeReleaseRef() noexcept {
        if (auto p = m_weakPtr.lock()) [[likely]]
            p->releaseWeakRef();
    }

