// === Unary Operators ===

REACTION_DEFINE_UNARY_OPERATOR(-, NegOp);
REACTION_DEFINE_UNARY_OPERATOR(!, NotOp);
REACTION_DEFINE_UNARY_OPERATOR(~, BitNotOp);

